import{_ as a,C as r,o,c as i,a2 as e,b as n,w as l,a as d,E,a3 as g}from"./chunks/framework.BODD28Fk.js";const A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"나의 할일 관리 (To-Do & Issue 전환)","description":"","frontmatter":{},"headers":[],"relativePath":"work-manage/todo.md","filePath":"work-manage/todo.md","lastUpdated":1793460388000}'),c={name:"work-manage/todo.md"};function C(B,t,u,h,m,p){const s=r("Mermaid");return o(),i("div",null,[t[1]||(t[1]=e('<h1 id="나의-할일-관리-to-do-issue-전환" tabindex="-1">나의 할일 관리 (To-Do &amp; Issue 전환) <a class="header-anchor" href="#나의-할일-관리-to-do-issue-전환" aria-label="Permalink to &quot;나의 할일 관리 (To-Do &amp; Issue 전환)&quot;">​</a></h1><blockquote><p><strong>나의 할일 관리</strong>는 하루 동안 처리해야 할 개인 작업과 빠른 메모를 기록하고, 필요할 때 단 한 번의 클릭으로 워크스페이스 공식 과업인 **업무(Issue)**로 승격시킬 수 있는 <strong>개인 업무 생산성 도구</strong>입니다.</p></blockquote><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+A+'" alt="나의 할일 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/todo.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="_1-개요-및-워크플로우" tabindex="-1">1. 개요 및 워크플로우 <a class="header-anchor" href="#_1-개요-및-워크플로우" aria-label="Permalink to &quot;1. 개요 및 워크플로우&quot;">​</a></h2><p>업무를 하다 보면 &quot;오후 2시 감리단 통화&quot;, &quot;자재 견적서 확인&quot;처럼 개인적으로 빠르게 메모해두고 체크해야 할 작은 일들이 수시로 발생합니다. 이를 종이나 별도 메모장에 적어두면 잊어버리거나 다른 팀원과 진행 상황을 공유하기 어렵습니다.</p><p>IBS의 <strong>나의 할일 관리</strong>는 개인 메모로 가볍게 시작한 할 일을 공식 프로젝트 업무로 자연스럽게 발전시킬 수 있는 최적의 워크플로우를 제공합니다.</p>',6)),(o(),n(g,null,{default:l(()=>[E(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%F0%9F%92%A1%20%EB%B2%88%EB%9C%A9%EC%9D%B4%EB%8A%94%20%EC%95%84%EC%9D%B4%EB%94%94%EC%96%B4%3Cbr%3E%EB%98%90%EB%8A%94%20%EA%B0%9C%EC%9D%B8%20%EB%A9%94%EB%AA%A8%22%5D%20--%3E%20B%5B%22%F0%9F%93%9D%20%EB%B9%A0%EB%A5%B8%20%ED%95%A0%EC%9D%BC%20%EB%93%B1%EB%A1%9D%3Cbr%3E(%ED%97%A4%EB%8D%94%2F%EC%9A%B0%EC%B8%A1%20%ED%8C%A8%EB%84%90)%22%5D%0A%20%20%20%20B%20--%3E%20C%7B%22%EC%A7%84%ED%96%89%20%EB%B0%8F%20%ED%99%95%EC%9E%A5%20%ED%8C%90%EB%8B%A8%22%7D%0A%20%20%20%20C%20--%20%22%EB%8B%A8%EC%88%9C%20%EA%B0%9C%EC%9D%B8%20%EC%B2%B4%ED%81%AC%22%20--%3E%20D%5B%22%E2%9C%85%20%EC%99%84%EB%A3%8C%20%EC%B2%B4%ED%81%AC%3Cbr%3E(%EC%B7%A8%EC%86%8C%EC%84%A0%20%ED%91%9C%EC%8B%9C)%22%5D%0A%20%20%20%20C%20--%20%22%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EA%B3%B5%EC%9A%A9%20%EA%B3%BC%EC%97%85%22%20--%3E%20E%5B%22%F0%9F%9A%80%20%EC%97%85%EB%AC%B4%EB%A1%9C%20%EC%A0%84%ED%99%98%3Cbr%3E(Convert%20to%20Issue)%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%F0%9F%8F%A2%20%EB%8C%80%EC%83%81%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EB%B0%B0%EC%A0%95%3Cbr%3E%EC%A0%9C%EB%AA%A9%C2%B7%EC%83%81%EC%84%B8%EB%82%B4%EC%9A%A9%20%EC%9E%85%EB%A0%A5%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%F0%9F%94%97%20%23%EC%97%85%EB%AC%B4%EB%B2%88%ED%98%B8%20%EB%B1%83%EC%A7%80%20%EC%97%B0%EA%B2%B0%3Cbr%3E%26%20%EC%9E%90%EB%8F%99%20%EC%99%84%EB%A3%8C%20%EC%B2%98%EB%A6%AC%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%F0%9F%91%A5%20%ED%8C%80%EC%9B%90%20%ED%98%91%EC%97%85%C2%B7%EC%A7%84%EC%B2%99%20%EA%B4%80%EB%A6%AC%3Cbr%3E(%EA%B3%B5%EC%8B%9D%20%EC%97%85%EB%AC%B4%20%EC%83%81%EC%84%B8)%22%5D%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<div class="tip custom-block"><p class="custom-block-title">💡 신입사원 실무 활용 팁</p><ul><li><strong>나만의 비공개 메모</strong>: 내가 등록한 할 일은 기본적으로 <strong>나에게만 보이는 비공개 데이터</strong>이므로 부담 없이 자유롭게 메모하세요.</li><li><strong>업무 승격 타이밍</strong>: 혼자 처리할 수 없는 과업이거나, 다른 동료에게 인계해야 하거나, 회의 및 보고가 필요한 사안으로 발전하면 즉시 <strong><code>업무로 전환</code></strong> 버튼을 눌러 공식 업무로 등록하세요.</li></ul></div><hr><h2 id="_2-할일-관리-진입-방법-3가지-경로" tabindex="-1">2. 할일 관리 진입 방법 (3가지 경로) <a class="header-anchor" href="#_2-할일-관리-진입-방법-3가지-경로" aria-label="Permalink to &quot;2. 할일 관리 진입 방법 (3가지 경로)&quot;">​</a></h2><p>IBS에서는 작업 중인 화면을 벗어나지 않고도 언제든지 할 일을 확인하고 추가할 수 있도록 3가지 진입 경로를 제공합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">진입 경로</th><th style="text-align:left;">위치 및 UI 표출</th><th style="text-align:left;">주요 특징 및 권장 사용 상황</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. 상단 헤더 알림 바</strong></td><td style="text-align:left;">상단 중앙 <strong><code>[&lt;i class=&quot;mdi mdi-calendar-check-outline&quot;&gt;&lt;/i&gt; 할일 N]</code></strong> 칩</td><td style="text-align:left;">남은 미완료 할 일 건수를 상시 모니터링하며, 클릭 시 전용 팝업 모달 호출</td></tr><tr><td style="text-align:left;"><strong>2. 사용자 프로필 메뉴</strong></td><td style="text-align:left;">우측 상단 아바타 클릭 ➔ <strong><code>[할일 관리 N]</code></strong> 메뉴</td><td style="text-align:left;">계정 설정과 함께 내 할 일 목록을 빠르게 열람할 때 사용</td></tr><tr><td style="text-align:left;"><strong>3. 우측 사이드 패널</strong></td><td style="text-align:left;">화면 우측 끝 사이드바 열기 ➔ <strong><code>오늘/할일</code></strong> 탭</td><td style="text-align:left;">결재 대기 문서 및 담당 업무와 함께 한 화면에서 인라인으로 할 일을 관리할 때 매우 유용</td></tr></tbody></table><hr><h2 id="_3-할-일-등록-및-기본-관리" tabindex="-1">3. 할 일 등록 및 기본 관리 <a class="header-anchor" href="#_3-할-일-등록-및-기본-관리" aria-label="Permalink to &quot;3. 할 일 등록 및 기본 관리&quot;">​</a></h2><h3 id="_1-새로운-할-일-등록" tabindex="-1">1) 새로운 할 일 등록 <a class="header-anchor" href="#_1-새로운-할-일-등록" aria-label="Permalink to &quot;1) 새로운 할 일 등록&quot;">​</a></h3><ul><li><strong>입력창</strong>: 할 일 목록 상단의 <strong><code>[여기에 할 일을 메모 하세요.]</code></strong> (또는 우측 사이드 패널의 <strong><code>[새로운 할 일 입력 후 추가...]</code></strong>) 입력창을 클릭합니다.</li><li><strong>등록</strong>: 할 일 내용을 작성한 뒤 키보드의 <code>Enter</code> 키를 누르거나 우측의 <code>[추가]</code> 버튼을 클릭하면 목록 최상단에 즉시 등록됩니다.</li></ul><h3 id="_2-완료-체크-및-취소선" tabindex="-1">2) 완료 체크 및 취소선 <a class="header-anchor" href="#_2-완료-체크-및-취소선" aria-label="Permalink to &quot;2) 완료 체크 및 취소선&quot;">​</a></h3><ul><li>할 일 좌측의 <strong>동그란 체크박스</strong>를 클릭하면 완료 처리되며, 제목에 취소선이 그어지고 텍스트가 옅은 색으로 변경됩니다.</li><li>다시 체크박스를 누르면 미완료 상태로 즉시 복구됩니다.</li><li>상단 헤더의 남은 할 일 뱃지 숫자가 실시간으로 차감/증가합니다.</li></ul><h3 id="_3-내용-수정-더블클릭" tabindex="-1">3) 내용 수정 (더블클릭) <a class="header-anchor" href="#_3-내용-수정-더블클릭" aria-label="Permalink to &quot;3) 내용 수정 (더블클릭)&quot;">​</a></h3><ul><li>팝업 모달창에서는 수정하고 싶은 할 일 제목을 <strong>마우스로 더블클릭</strong>하면 인라인 편집 모드로 전환됩니다.</li><li>내용을 수정한 후 <code>Enter</code> 키를 누르거나 입력창 바깥을 클릭하면 저장이 완료됩니다. 수정을 취소하려면 <code>Esc</code> 키를 누릅니다.</li></ul><h3 id="_4-할-일-삭제" tabindex="-1">4) 할 일 삭제 <a class="header-anchor" href="#_4-할-일-삭제" aria-label="Permalink to &quot;4) 할 일 삭제&quot;">​</a></h3><ul><li>목록 항목에 마우스를 올렸을 때 우측 끝에 나타나는 <strong><code>[✕]</code> 삭제 아이콘</strong>을 클릭하면 해당 할 일이 목록에서 깔끔하게 제거됩니다.</li></ul><h3 id="_5-보기-필터-및-일괄-정리" tabindex="-1">5) 보기 필터 및 일괄 정리 <a class="header-anchor" href="#_5-보기-필터-및-일괄-정리" aria-label="Permalink to &quot;5) 보기 필터 및 일괄 정리&quot;">​</a></h3><p>팝업 모달창 하단 툴바에서는 목록을 효율적으로 정리할 수 있는 컨트롤을 제공합니다:</p><ul><li><strong>All (전체)</strong>: 완료 여부와 관계없이 등록된 모든 할 일을 표시합니다.</li><li><strong>Active (진행 중)</strong>: 아직 완료되지 않은 진행 중인 할 일만 모아서 봅니다.</li><li><strong>Completed (완료됨)</strong>: 완료 처리된 항목만 필터링하여 확인합니다.</li><li><strong>Clear completed</strong>: 완료된 모든 할 일을 한 번에 목록에서 삭제 정리합니다.</li></ul><hr><h2 id="_4-핵심-기능-개인-할-일을-공식-업무-issue-로-전환" tabindex="-1">4. 핵심 기능: 개인 할 일을 공식 업무(Issue)로 전환 <a class="header-anchor" href="#_4-핵심-기능-개인-할-일을-공식-업무-issue-로-전환" aria-label="Permalink to &quot;4. 핵심 기능: 개인 할 일을 공식 업무(Issue)로 전환&quot;">​</a></h2><p>단순한 개인 메모로 시작했던 일도 프로젝트가 구체화되면 팀원들과 공유하고 진척을 관리해야 하는 공식 과업이 됩니다. IBS는 이를 위해 <strong>업무 전환(Convert to Issue)</strong> 기능을 제공합니다.</p><h3 id="🚀-업무-전환-단계별-가이드" tabindex="-1">🚀 업무 전환 단계별 가이드 <a class="header-anchor" href="#🚀-업무-전환-단계별-가이드" aria-label="Permalink to &quot;🚀 업무 전환 단계별 가이드&quot;">​</a></h3><ol><li><strong>전환 버튼 클릭</strong>: <ul><li>할 일 항목 우측의 <strong><code>[업무로 전환]</code></strong> 아이콘(<i class="mdi mdi-transfer-right text-primary"></i>)을 클릭합니다.</li></ul></li><li><strong>업무 전환 팝업 작성</strong>: <ul><li><strong>대상 워크스페이스</strong> (<span class="text-danger">*</span>필수): 업무를 등록할 프로젝트 워크스페이스를 드롭다운에서 선택합니다.</li><li><strong>업무 제목</strong> (<span class="text-danger">*</span>필수): 기존 할 일 제목이 자동으로 채워지며, 필요에 따라 더 구체적으로 보완합니다.</li><li><strong>설명</strong> (선택): 업무의 배경, 진행 요청 사항, 참고 링크 등 상세 내용을 입력합니다.</li></ul></li><li><strong><code>[업무로 전환]</code> 버튼 클릭</strong>: <ul><li>입력 완료 후 하단의 파란색 <strong><code>[업무로 전환]</code></strong> 버튼을 누릅니다.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">📸 업무 전환 후 자동 연결 효과</p><ul><li><strong>공식 업무 자동 발급</strong>: 선택한 워크스페이스에 즉시 고유한 업무 번호(예: <code>#104</code>)를 가진 신규 공식 업무가 생성됩니다.</li><li><strong>할 일 자동 완료 처리</strong>: 기존 할 일 항목은 완료 상태로 자동 변경되며, 제목 옆에 파란색 <strong><code>[#104]</code> 뱃지</strong>가 부착됩니다.</li><li><strong>1초 만에 업무로 바로가기</strong>: 화면 상단에 녹색 완료 안내 배너와 함께 <strong><code>[업무 바로가기]</code></strong> 버튼이 나타나며, 클릭 즉시 생성된 공식 업무의 상세 페이지로 이동합니다.</li><li><strong>영구적인 연결 링크</strong>: 추후 할 일 목록에서 <strong><code>[#104]</code> 뱃지</strong>를 클릭하기만 해도 언제든지 해당 공식 업무 화면으로 즉시 연결됩니다.</li></ul></div><hr><h2 id="_5-데이터-권한-및-공개-범위-안내" tabindex="-1">5. 데이터 권한 및 공개 범위 안내 <a class="header-anchor" href="#_5-데이터-권한-및-공개-범위-안내" aria-label="Permalink to &quot;5. 데이터 권한 및 공개 범위 안내&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">할 일과 공식 업무의 데이터 공개 범위 차이</p><p></p><ul><li><strong>할 일(To-Do) 상태일 때</strong>: <ul><li>해당 할 일을 작성한 <strong>본인에게만</strong> 표출되며, 관리자나 다른 동료에게 일체 노출되지 않는 철저한 개인 데이터입니다.</li></ul></li><li><strong>공식 업무(Issue)로 전환된 후</strong>: <ul><li>지정한 워크스페이스의 구성원 모두가 조회하고 협업할 수 있는 <strong>공식 자산</strong>으로 승격됩니다.</li><li>워크스페이스의 업무 목록, 로드맵, 업무실행내역(Activity)에 공식 기록으로 등록되어 진척률 및 담당자 관리가 시작됩니다.</li></ul></li></ul></div>',27))])}const D=a(c,[["render",C]]);export{b as __pageData,D as default};
